"use strict";(self.webpackChunkcoursesmith_site=self.webpackChunkcoursesmith_site||[]).push([["2712"],{4611(e,n,t){t.r(n),t.d(n,{metadata:()=>a,default:()=>u,frontMatter:()=>r,contentTitle:()=>l,toc:()=>h,assets:()=>d});var a=JSON.parse('{"id":"m1-ai-map-start-here/lesson","title":"Lesson: START HERE \u2014 The AI Map: ML \u2192 Deep Learning \u2192 LLMs \u2192 Agents","description":"Where does ChatGPT actually fit?","source":"@site/docs/m1-ai-map-start-here/lesson.md","sourceDirName":"m1-ai-map-start-here","slug":"/m1-ai-map-start-here/lesson","permalink":"/aiml-foundations-site/docs/m1-ai-map-start-here/lesson","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":1,"frontMatter":{"sidebar_position":1,"title":"Lesson: START HERE \u2014 The AI Map: ML \u2192 Deep Learning \u2192 LLMs \u2192 Agents"},"sidebar":"courseSidebar","previous":{"title":"Environment","permalink":"/aiml-foundations-site/docs/setup/environment"},"next":{"title":"Lab: START HERE \u2014 The AI Map: ML \u2192 Deep Learning \u2192 LLMs \u2192 Agents","permalink":"/aiml-foundations-site/docs/m1-ai-map-start-here/lab"}}'),o=t(4848),s=t(8453),i=t(7684);let r={sidebar_position:1,title:"Lesson: START HERE \u2014 The AI Map: ML \u2192 Deep Learning \u2192 LLMs \u2192 Agents"},l="START HERE \u2014 The AI Map: ML \u2192 Deep Learning \u2192 LLMs \u2192 Agents",d={},h=[{value:"Where does ChatGPT actually fit?",id:"where-does-chatgpt-actually-fit",level:2},{value:"Module slides",id:"module-slides",level:2},{value:"The map is nested, not a list",id:"the-map-is-nested-not-a-list",level:2},{value:"One more label you&#39;ll need: RAG",id:"one-more-label-youll-need-rag",level:2},{value:"The vendor-call test",id:"the-vendor-call-test",level:2},{value:"The four projects you&#39;ll build",id:"the-four-projects-youll-build",level:2},{value:"What&#39;s next",id:"whats-next",level:2}];function c(e){let n={admonition:"admonition",em:"em",h1:"h1",h2:"h2",header:"header",li:"li",mermaid:"mermaid",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(n.header,{children:(0,o.jsx)(n.h1,{id:"start-here--the-ai-map-ml--deep-learning--llms--agents",children:"START HERE \u2014 The AI Map: ML \u2192 Deep Learning \u2192 LLMs \u2192 Agents"})}),"\n",(0,o.jsx)(n.h2,{id:"where-does-chatgpt-actually-fit",children:"Where does ChatGPT actually fit?"}),"\n",(0,o.jsx)(n.p,{children:"You use AI products every day \u2014 a chat assistant, a code completion tool, a fraud alert on your\nbank statement, a recommendation feed. If someone asked you in a review or a vendor call \"is that\nmachine learning, or is it a language model, or is it an agent?\" \u2014 could you answer without\nhedging? Most technical professionals can't, and it's not because the ideas are hard. It's because\nnobody ever drew the boundaries. This module draws them."}),"\n",(0,o.jsx)(n.p,{children:"By the end of this lesson you'll be able to place ChatGPT, Claude, a fraud-detection model, and a\nresearch agent on one map \u2014 and know exactly which question to ask about each one."}),"\n",(0,o.jsx)(n.h2,{id:"module-slides",children:"Module slides"}),"\n",(0,o.jsx)(n.p,{children:"Walk this short whiteboard deck for the big picture before the hands-on lab, or open it fullscreen."}),"\n",(0,o.jsx)(i.A,{src:"decks/m1-ai-map-start-here.html",title:"M1 \u2014 START HERE \u2014 The AI Map"}),"\n",(0,o.jsx)(n.h2,{id:"the-map-is-nested-not-a-list",children:"The map is nested, not a list"}),"\n",(0,o.jsxs)(n.p,{children:[(0,o.jsx)(n.strong,{children:"Analogy:"}),' Think about how you\'d describe your own job to someone outside tech. You wouldn\'t\nsay "I do computers" \u2014 that tells them nothing. You\'d narrow it: "technology" \u2192 "software\nengineering" \u2192 "backend infrastructure" \u2192 maybe "the payments team." Each word is a real,\ncorrect answer, just at a different zoom level. Nobody is wrong; they\'re standing at different\ndistances from the same building.']}),"\n",(0,o.jsx)(n.p,{children:'The AI field works exactly the same way. "AI," "machine learning," "deep learning," and "LLM"\nare not four different technologies competing for the same job \u2014 they\'re four zoom levels on\nthe same building, each one narrower and more specific than the last.'}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Artificial Intelligence"})," is the widest circle: the goal of getting a machine to do something\nthat looks like it requires judgment. It's a goal, not a method \u2014 a rule-based tax calculator,\na chess engine's search tree, and ChatGPT are all \"AI\" by this definition, even though almost\nnothing else about them is similar."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Machine Learning"}),' is one method inside that circle: instead of an engineer hand-writing the\nrules ("if the email contains these 40 words, mark it spam"), you show the system thousands of\nlabeled examples and let it find the pattern itself. The rules come from data, not from a\ndeveloper\'s if/else tree.']}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Deep Learning"}),' is one technique inside ML: instead of a single, simple function, you stack\nmany layers of small transformations on top of each other \u2014 a "neural network" \u2014 so the system\ncan learn patterns in messy, high-dimensional data like pixels, audio, or raw text that simpler\nML methods handle poorly.']}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Large Language Models"})," are one specific product of deep learning: a network trained on\nenormous amounts of text to do one narrow thing extremely well \u2014 predict the next chunk of text\ngiven everything before it. Do that at scale, on the whole internet, and the result can answer\nquestions, write code, and hold a conversation."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"Agents"})," sit outside this nesting, not inside it. An agent is not a smarter model \u2014 it's an\n",(0,o.jsx)(n.em,{children:"architecture"}),": an LLM wrapped with tools it can call, memory it can read and write, and a loop\nthat lets it take more than one step before handing control back to you."]}),"\n"]}),"\n",(0,o.jsx)(n.mermaid,{value:'graph TD\n    subgraph AI["Artificial Intelligence \u2014 any technique that produces judgment-like behavior"]\n        subgraph ML["Machine Learning \u2014 rules learned from data, not hand-coded"]\n            subgraph DL["Deep Learning \u2014 layered neural networks for messy, high-dimensional data"]\n                LLM["Large Language Models \u2014 trained to predict the next chunk of text"]\n            end\n        end\n    end\n    LLM --\x3e|"wrapped with tools + memory + a loop"| AGENT["Agents \u2014 act across multiple steps, not just answer once"]'}),"\n",(0,o.jsx)(n.p,{children:"ChatGPT's raw text generation lives in the LLM region. The moment it browses the web, runs code,\nor checks your calendar across several steps to complete a task, you've crossed into the agent\nregion \u2014 same underlying model, different architecture wrapped around it. Claude, Gemini, and\nGPT-5-class models all live in the LLM region; Claude Code, a research assistant that searches\nand summarizes, or a support bot that files a ticket on your behalf, live in the agent region\nbecause of what wraps the model, not because the model itself changed."}),"\n",(0,o.jsx)(n.admonition,{title:"Why this map matters more than it looks like it should",type:"tip",children:(0,o.jsx)(n.p,{children:'The four regions don\'t just organize trivia \u2014 they change the questions you ask. "How was it\ntrained, and on what data?" is an ML/DL question. "How many tokens am I paying for, and what\'s\nin the context window?" is an LLM question. "What tools can it call, and what happens if it calls\nthe wrong one?" is an agent question. Ask an ML question about an agent and you\'ll miss the risk\nthat actually bites you.'})}),"\n",(0,o.jsx)(n.h2,{id:"one-more-label-youll-need-rag",children:"One more label you'll need: RAG"}),"\n",(0,o.jsxs)(n.p,{children:["Before you test yourself, one more term belongs on the map \u2014 not as a new region, but as a\n",(0,o.jsx)(n.strong,{children:"pattern layered onto the LLM or agent regions"}),": ",(0,o.jsx)(n.strong,{children:"RAG (retrieval-augmented generation)"}),". A\nplain LLM only knows what was in its training data. RAG looks up relevant text from a source you\ncontrol \u2014 your documents, your product's help pages \u2014 right before generating an answer, so the\nresponse is grounded in something real instead of only what the model memorized. You'll classify\nscenarios that use it in a moment, and you'll build a small RAG pipeline yourself in Module 6."]}),"\n",(0,o.jsx)(n.h2,{id:"the-vendor-call-test",children:"The vendor-call test"}),"\n",(0,o.jsx)(n.p,{children:'Here\'s where this stops being trivia. Say your team is reviewing three vendor pitches this\nquarter: one sells "AI-powered anomaly detection," one sells "an LLM copilot for your support\nteam," and one sells "an autonomous agent that resolves tickets end to end." All three say "AI."\nIf you can\'t place each on the map, you ask the same generic question of all three and learn\nnothing. If you can, you know exactly what to ask:'}),"\n",(0,o.jsxs)(n.ul,{children:["\n",(0,o.jsx)(n.li,{children:"The anomaly-detection pitch is almost certainly classical ML \u2014 ask about training data,\nretraining cadence, and false-positive rate."}),"\n",(0,o.jsx)(n.li,{children:"The copilot is an LLM sitting in a chat window \u2014 ask about the context window, hallucination\nrate, and what happens when it doesn't know something."}),"\n",(0,o.jsx)(n.li,{children:"The end-to-end resolver is an agent \u2014 ask what tools it can call, what happens when it calls\nthe wrong one, and who's accountable when it acts on bad information."}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:'Same word, "AI," three completely different sets of risks. The map is what lets you tell them\napart in the room, not after the postmortem.'}),"\n",(0,o.jsx)(n.admonition,{title:"This is not new \u2014 but it is now unavoidable",type:"note",children:(0,o.jsx)(n.p,{children:"None of these four ideas is new; supervised learning is decades old and neural networks older\nstill. What's new is that all four now show up in the same product, sometimes the same feature,\nand a technical professional who can't place them apart gets stuck asking the wrong question in\nevery AI conversation at work. That's the gap this module closes."})}),"\n",(0,o.jsx)(n.h2,{id:"the-four-projects-youll-build",children:"The four projects you'll build"}),"\n",(0,o.jsx)(n.p,{children:"This course is not four modules of theory followed by a project \u2014 it's one growing project,\nbuilt one capability at a time, starting in the next few modules:"}),"\n",(0,o.jsxs)(n.ol,{children:["\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"A predictor"})," \u2014 a classical ML model that forecasts a number from historical data (Module 3)."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"A digit classifier"})," \u2014 a small neural network, so you feel deep learning working, not just\nread about it (Module 4)."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"An LLM-powered tool"})," \u2014 your first real API call to a language model, wired into a small\ncommand-line tool (Module 5, and you'll take the very first step toward it in today's lab)."]}),"\n",(0,o.jsxs)(n.li,{children:[(0,o.jsx)(n.strong,{children:"An autonomous agent"})," \u2014 a system that reasons in steps and calls tools on its own to\nresearch and summarize real information (Module 6). This is the course's marquee moment: you\nwill watch a finished agent run live before you build your own."]}),"\n"]}),"\n",(0,o.jsx)(n.p,{children:"By the capstone (Module 9), all four converge into one assistant \u2014 an LLM core, an agent loop,\nretrieval over a PDF you choose, and an API you can call like a real client. You run it, you break\nit on purpose, and you walk away with something worth demoing."}),"\n",(0,o.jsx)(n.h2,{id:"whats-next",children:"What's next"}),"\n",(0,o.jsx)(n.p,{children:"Now that you have the map, Module 2 gives you the vocabulary that goes with it \u2014 tokens,\nembeddings, context windows, RAG, agents, hallucination \u2014 so the next AI headline or product page\nreads as words you actually know, not noise."})]})}function u(e={}){let{wrapper:n}={...(0,s.R)(),...e.components};return n?(0,o.jsx)(n,{...e,children:(0,o.jsx)(c,{...e})}):c(e)}},7684(e,n,t){t.d(n,{A:()=>s});var a=t(4848);t(6540);var o=t(6497);function s({src:e,title:n="Slides"}){let t=(0,o.Ay)(e);return(0,a.jsxs)("div",{className:"deck_nWXz",children:[(0,a.jsxs)("div",{className:"bar_dOoE",children:[(0,a.jsxs)("span",{className:"label_ZSLR",children:["\u25B6 ",n]}),(0,a.jsx)("a",{className:"full_PrDQ",href:t,target:"_blank",rel:"noopener noreferrer",children:"Open fullscreen \u2197"})]}),(0,a.jsx)("div",{className:"frame_M4DO",children:(0,a.jsx)("iframe",{src:t,title:n,loading:"lazy",allowFullScreen:!0})})]})}},8453(e,n,t){t.d(n,{R:()=>i,x:()=>r});var a=t(6540);let o={},s=a.createContext(o);function i(e){let n=a.useContext(s);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function r(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:i(e.components),a.createElement(s.Provider,{value:n},e.children)}}}]);